<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('programme_manager');
require_once __DIR__ . '/_management_suite_helpers.php';
$user=current_user();$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);if($managerId<=0){http_response_code(403);exit('Invalid Programme Manager account.');}
$currentPage='supervisor_monitoring';$pageTitle='Supervisor Performance & Workload';$flashes=render_flashes();$errors=[];$tableReady=pm_table_exists($conn,'cohorts');$programmes=pm_suite_programmes($conn,$managerId);$cohorts=pm_suite_cohorts($conn,$managerId);

$rows=[];$stats=['supervisors'=>0,'cohorts'=>0,'candidates'=>0,'updates'=>0,'attendance'=>0,'needs_attention'=>0];
$progressCountExpr=pm_table_exists($conn,'candidate_progress_history')?"(SELECT COUNT(*) FROM candidate_progress_history h WHERE h.cohort_id=c.id AND h.created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY))":"0";
$lastProgressExpr=pm_table_exists($conn,'candidate_progress_history')?"(SELECT MAX(h.created_at) FROM candidate_progress_history h WHERE h.cohort_id=c.id)":"NULL";
$attendanceCountExpr=pm_table_exists($conn,'candidate_attendance')?"(SELECT COUNT(*) FROM candidate_attendance a WHERE a.cohort_id=c.id AND a.session_date>=DATE_SUB(CURDATE(),INTERVAL 30 DAY))":"0";
$attendancePresentExpr=pm_table_exists($conn,'candidate_attendance')?"(SELECT SUM(CASE WHEN LOWER(a.status) IN ('present','attended','late') THEN 1 ELSE 0 END) FROM candidate_attendance a WHERE a.cohort_id=c.id AND a.session_date>=DATE_SUB(CURDATE(),INTERVAL 30 DAY))":"0";
$overdueMilestonesExpr=pm_table_exists($conn,'programme_milestones')?"(SELECT COUNT(*) FROM programme_milestones m WHERE m.cohort_id=c.id AND m.status<>'completed' AND m.due_date<CURDATE())":"0";
$sql="SELECT c.id cohort_id,c.name cohort_name,c.status cohort_status,c.max_capacity,c.supervisor_id, p.name programme_name, TRIM(CONCAT(COALESCE(u.first_name,''),' ',COALESCE(u.last_name,''))) supervisor_name, u.email supervisor_email, COUNT(DISTINCT CASE WHEN cp.status<>'withdrawn' THEN cp.user_id END) candidate_count, COUNT(DISTINCT CASE WHEN cp.status='completed' THEN cp.user_id END) completed_count, {$progressCountExpr} updates_30d, {$lastProgressExpr} last_update, {$attendanceCountExpr} attendance_30d, {$attendancePresentExpr} attended_30d, {$overdueMilestonesExpr} overdue_milestones FROM cohorts c JOIN programmes p ON p.id=c.programme_id LEFT JOIN users u ON u.id=c.supervisor_id LEFT JOIN cohort_participants cp ON cp.cohort_id=c.id WHERE p.programme_manager_id=? GROUP BY c.id,c.name,c.status,c.max_capacity,c.supervisor_id,p.name,u.first_name,u.last_name,u.email ORDER BY supervisor_name,p.name,c.name";
$s=$conn->prepare($sql);if($s){$s->bind_param('i',$managerId);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();} $supervisorSet=[];foreach($rows as $r){if(!empty($r['supervisor_id']))$supervisorSet[(int)$r['supervisor_id']]=true;$stats['cohorts']++;$stats['candidates']+=(int)$r['candidate_count'];$stats['updates']+=(int)$r['updates_30d'];$stats['attendance']+=(int)$r['attendance_30d'];if(empty($r['supervisor_id'])||(int)$r['updates_30d']===0||(int)$r['overdue_milestones']>0)$stats['needs_attention']++;}$stats['supervisors']=count($supervisorSet);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=e($pageTitle)?> | Investhood IT</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="<?=url('css/styles.css')?>"><link rel="stylesheet" href="<?=url('css/programme_manager_enhancements.css')?>?v=20261026"><link rel="stylesheet" href="<?=url('css/programme_management_suite.css')?>?v=20261026"></head><body class="dashboard-page"><div class="dashboard"><?php require __DIR__.'/sidebar.php';?><main class="dashboard__main"><?php require __DIR__.'/navbar.php';?><div class="pm-suite"><?=$flashes?>

<section class="pm-suite-hero"><div><span class="pm-suite-eyebrow">Team delivery oversight</span><h1>Supervisor Performance &amp; Workload Monitoring</h1><p>Review supervisor assignments, cohort size and capacity, candidate progress updates, attendance activity, and programme milestones that may require follow-up. Indicators are derived from existing portal records.</p></div></section><?php if(!pm_table_exists($conn,'candidate_progress_history')):?><div class="pm-suite-notice">Candidate progress history is not available yet. Supervisor progress-update counts will populate after progress history is enabled and supervisors record updates.</div><?php endif;?>
<section class="pm-suite-kpis"><article class="pm-suite-kpi"><small>Supervisors assigned</small><strong><?=$stats['supervisors']?></strong><span>Distinct supervisors across your cohorts</span></article><article class="pm-suite-kpi"><small>Assigned cohorts</small><strong><?=$stats['cohorts']?></strong><span>Within your programme portfolio</span></article><article class="pm-suite-kpi"><small>Active participants</small><strong><?=$stats['candidates']?></strong><span>Excludes withdrawn participants</span></article><article class="pm-suite-kpi"><small>Needs attention</small><strong><?=$stats['needs_attention']?></strong><span>Unassigned, no recent updates, or overdue milestones</span></article></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Supervisor workload by cohort</h2><p>Progress activity uses the last 30 days. Attendance activity is based on recorded attendance sessions in the last 30 days. These indicators support review and are not a standalone performance rating.</p></div><div class="pm-suite-table-wrap"><table class="pm-suite-table"><thead><tr><th>Supervisor / cohort</th><th>Candidate workload</th><th>Progress updates</th><th>Attendance activity</th><th>Outstanding work</th><th>Monitoring signal</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="pm-suite-empty">No cohorts are currently associated with your assigned programmes.</td></tr><?php else:foreach($rows as $r):$rate=(int)$r['max_capacity']>0?min(100,round(((int)$r['candidate_count']/(int)$r['max_capacity'])*100)):0;$attTotal=(int)$r['attendance_30d'];$attended=(int)($r['attended_30d']??0);$attRate=$attTotal>0?round(($attended/$attTotal)*100):null;$noSupervisor=empty($r['supervisor_id']);$noUpdates=(int)$r['updates_30d']===0;$attention=$noSupervisor||$noUpdates||(int)$r['overdue_milestones']>0;?><tr><td><strong><?=e(trim($r['supervisor_name']??'')?:'Unassigned supervisor')?></strong><span class="pm-suite-muted"><?=e($r['supervisor_email']??'No supervisor contact')?></span><span class="pm-suite-muted"><?=e($r['programme_name'])?> · <?=e($r['cohort_name'])?></span></td><td><strong><?=(int)$r['candidate_count']?> candidates</strong><span class="pm-suite-muted"><?=((int)$r['max_capacity']>0)?((int)$r['max_capacity'].' capacity'):'Capacity not set'?></span><?php if((int)$r['max_capacity']>0):?><div class="pm-suite-progress"><span style="width:<?=$rate?>%"></span></div><span class="pm-suite-muted"><?=$rate?>% capacity used</span><?php endif;?><span class="pm-suite-muted"><?=(int)$r['completed_count']?> completed</span></td><td><strong><?=(int)$r['updates_30d']?></strong><span class="pm-suite-muted">Updates in 30 days</span><span class="pm-suite-muted">Last: <?=!empty($r['last_update'])?e(date('d M Y',strtotime($r['last_update']))):'No update recorded'?></span></td><td><strong><?=$attTotal?></strong><span class="pm-suite-muted">Attendance records in 30 days</span><span class="pm-suite-muted"><?=$attRate!==null?($attRate.'% present/attended'): 'No attendance data'?></span></td><td><span class="pm-suite-pill <?=(int)$r['overdue_milestones']>0?'bad':'good'?>"><?=(int)$r['overdue_milestones']?> overdue milestones</span><span class="pm-suite-muted">Cohort milestones past due</span></td><td><?php if($noSupervisor):?><span class="pm-suite-pill bad">Assign supervisor</span><?php elseif($noUpdates):?><span class="pm-suite-pill warn">Review progress activity</span><?php elseif((int)$r['overdue_milestones']>0):?><span class="pm-suite-pill warn">Follow up overdue work</span><?php else:?><span class="pm-suite-pill good">No immediate flag</span><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>How to interpret the monitoring indicators</h2><p>Use the indicators to guide conversations and support, not as automatic judgments of supervisor quality.</p></div><div style="padding:1rem 1.2rem;display:grid;gap:.65rem;font-size:.82rem;line-height:1.55"><div><span class="pm-suite-pill bad">Assign supervisor</span> The cohort has no supervisor assigned in the cohort record.</div><div><span class="pm-suite-pill warn">Review progress activity</span> No progress history was recorded for this cohort in the monitored dataset. Confirm whether an update is due.</div><div><span class="pm-suite-pill warn">Follow up overdue work</span> At least one milestone associated with the cohort is past its due date and not completed.</div><div>Attendance percentages are calculated from recorded attendance entries in the 30-day window; missing records are not treated as absences.</div></div></section>
</div></main></div><script src="<?=url('js/programme_manager_enhancements.js')?>?v=20261026"></script><script src="<?=url('js/original_pm_sidebar.js')?>?v=20261026"></script></body></html>
